468	    @Override
469	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
470	        Owner owner = this.clinicService.findOwnerById(ownerId);
471	        if (owner == null) {
472	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
473	        }
474	        HttpHeaders headers = new HttpHeaders();
475	        Pet pet = petMapper.toPet(petFieldsDto);
476	        owner.setId(ownerId);
477	        pet.setOwner(owner);
478	        pet.getType().setName(null);
479	        this.clinicService.savePet(pet);
480	        PetDto petDto = petMapper.toPetDto(pet);
481	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
482	            .buildAndExpand(pet.getId()).toUri());
483	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
484	    }
