486	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
487	    @Override
488	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
489	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
490	        if (currentOwner != null) {
491	            Pet currentPet = this.clinicService.findPetById(petId);
492	            if (currentPet != null) {
493	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
494	                currentPet.setName(petFieldsDto.getName());
495	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
496	                this.clinicService.savePet(currentPet);
497	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
498	            }
499	        }
500	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
501	    }
