503	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
504	    @Override
505	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
506	        HttpHeaders headers = new HttpHeaders();
507	        Visit visit = visitMapper.toVisit(visitFieldsDto);
508	        Pet pet = new Pet();
509	        pet.setId(petId);
510	        visit.setPet(pet);
511	        this.clinicService.saveVisit(visit);
512	        VisitDto visitDto = visitMapper.toVisitDto(visit);
513	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
514	            .buildAndExpand(visit.getId()).toUri());
515	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
516	    }
517	
518	
519	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
520	    @Override
521	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
522	        Owner owner = this.clinicService.findOwnerById(ownerId);
523	        if (owner != null) {
