531	
532	    /** Matches a well-formed postcode: exactly 4 digits. */
533	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
534	
535	    /**
536	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
537	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
538	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
539	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
540	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
541	     */
542	    private static boolean isPostcodeValidForCity(Owner owner) {
543	        String postcode = owner.getPostcode();
544	        if (postcode == null) {
545	            return true;
546	        }
547	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
548	            return false;
549	        }
550	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
551	        if (range == null) {
552	            return true;
553	        }
554	        int value = Integer.parseInt(postcode);
555	        return value >= range[0] && value <= range[1];
556	    }
557	
558	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
559	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
560	
561	    /**
562	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
563	     * code are kept when present; otherwise country code '+61' is assumed and a single
564	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
565	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
566	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
567	     * Returns {@code null} when the number cannot form a valid E.164 value.
568	     */
569	    private static String normalizeTelephone(String telephone) {
570	        if (telephone == null) {
571	            return null;
572	        }
573	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
574	        String e164;
575	        if (cleaned.startsWith("+")) {
576	            e164 = cleaned;
577	        } else {
578	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
579	            e164 = "+61" + national;
580	        }
581	        if (!E164_PATTERN.matcher(e164).matches()) {
582	            return null;
583	        }
584	        return hasValidNationalNumberLength(e164) ? e164 : null;
585	    }
586	
587	    /**
588	     * Whether the national number of a well-formed E.164 value has the length required for its
589	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
590	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
591	     */
592	    private static boolean hasValidNationalNumberLength(String e164) {
593	        String countryCode = Owner.countryCodeOf(e164);
594	        if (countryCode == null) {
595	            return true;
596	        }
597	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
598	    }
599	
600	    /**
601	     * Compute and assign the derived attributes carried by a newly registered owner: the member id,
602	     * household id, namesake count and household member count. Each is derived from the owner's
603	     * already-normalized fields and the existing owner population, so this must run before the owner
604	     * is saved, while the counts still exclude the owner being created.
605	     *
606	     * <p>{@code declaredMember} is true when the owner was created into an existing household by
607	     * setting {@code sharesHousehold}: such an owner is a declared, not a suspected, household member,
608	     * so it is never flagged as a possible duplicate; otherwise the usual possible-duplicate check
609	     * runs (and, since a create that reaches here shares no existing household, does not flag it).
610	     */
611	    private void assignRegistrationAttributes(Owner owner, boolean declaredMember) {
612	        owner.setMemberId(generateMemberId(owner));
613	        owner.setHouseholdId(householdId(owner));
614	        owner.setNamesakeCount(countNamesakes(owner));
615	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
616	        owner.setMembershipLevelCap(membershipLevelCapForHousehold(owner));
617	        if (declaredMember) {
618	            owner.setPossibleDuplicate(false);
619	            owner.setPossibleDuplicateOf(null);
620	        } else {
621	            assignPossibleDuplicate(owner);
622	        }
623	    }
624	
625	    /**
626	     * Flag {@code owner} as a possible duplicate when, though not a hard duplicate (its create having
627	     * already cleared the {@link #isDuplicate} identity gate), it shares an existing owner's postcode
628	     * and last-name {@link #soundex(String) Soundex} yet resolves to a different {@link #identityKey}.
629	     * Sets {@code possibleDuplicate} accordingly and, when true, {@code possibleDuplicateOf} to the
630	     * matching owner's id. Runs before save, against the existing owner population.
631	     */
632	    private void assignPossibleDuplicate(Owner owner) {
633	        Integer matchId = findPossibleDuplicateOf(owner);
634	        owner.setPossibleDuplicate(matchId != null);
635	        owner.setPossibleDuplicateOf(matchId);
636	    }
637	
638	    /**
639	     * The id of an existing owner that shares {@code owner}'s postcode and last-name
640	     * {@link #soundex(String) Soundex} but resolves to a different {@link #identityKey}, or
641	     * {@code null} when there is none. Because the telephone is part of the identity key, two owners
642	     * with the same last name and postcode but different telephones differ in key and so match here,
643	     * making the later a soft (possible) duplicate rather than a hard conflict. When several match,
644	     * the lowest id is returned. An owner without a postcode never matches.
645	     */
646	    private Integer findPossibleDuplicateOf(Owner owner) {
647	        String postcode = owner.getPostcode();
648	        if (postcode == null) {
649	            return null;
650	        }
651	        String soundex = soundex(owner.getLastName());
652	        String identityKey = owner.getIdentityKey();
653	        return this.clinicService.findAllOwners().stream()
654	            .filter(existing -> !existing.isDeleted())
655	            .filter(existing -> existing.getId() != null
656	                && postcode.equals(existing.getPostcode())
657	                && soundex(existing.getLastName()).equals(soundex)
658	                && !identityKey.equals(existing.getIdentityKey()))
659	            .map(Owner::getId)
660	            .min(Integer::compareTo)
661	            .orElse(null);
662	    }
663	
664	    /**
665	     * Build {@code owner}'s member id '<REGION><FY><HASH8><CHK>': REGION is the region code stamped
666	     * inside the owner's identifiers ({@link Owner#getIdentityRegionCode()}), FY the two-digit
667	     * {@link Owner#fiscalYearSegment(LocalDate) fiscal-year segment} of the business-day-adjusted
668	     * {@link Owner#getRegistrationDate() registration date}, HASH8 the first 8 upper-case hex
669	     * characters of SHA-256 over the owner's already-normalized telephone concatenated with the
670	     * owner's last name, and CHK a single {@link Owner#luhnCheckDigit(String) Luhn check digit} over
671	     * the digits of '<REGION><FY><HASH8>' (e.g. 'NSW271A2B3C4D5'). The identity is otherwise a pure
672	     * function of the region, fiscal year and the (telephone, last name) pair; only when the computed
673	     * id collides with an existing owner's member id is it de-duplicated by appending '-<n>' with the
674	     * smallest {@code n} of 2 or more that makes it unique (e.g. 'NSW271A2B3C4D5-2').
675	     */
676	    private String generateMemberId(Owner owner) {
677	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
678	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
679	        String hash8 = Owner.sha256Hex(telephone + lastName).substring(0, 8);
680	        String core = owner.getIdentityRegionCode()
681	            + Owner.fiscalYearSegment(owner.getRegistrationDate()) + hash8;
682	        String base = core + Owner.luhnCheckDigit(core);
683	        return deduplicateMemberId(base);
684	    }
685	
686	    /**
687	     * De-duplicate a computed member id against the existing owner population: when {@code base}
688	     * is not already in use it is returned unchanged; otherwise '-<n>' is appended with the smallest
689	     * {@code n} of 2 or more that yields an id no existing owner carries.
690	     */
691	    private String deduplicateMemberId(String base) {
692	        Set<String> existing = this.clinicService.findAllOwners().stream()
693	            .map(Owner::getMemberId)
694	            .filter(code -> code != null)
695	            .collect(java.util.stream.Collectors.toSet());
696	        if (!existing.contains(base)) {
697	            return base;
698	        }
699	        int n = 2;
700	        while (existing.contains(base + "-" + n)) {
701	            n++;
702	        }
703	        return base + "-" + n;
704	    }
705	
706	    /**
707	     * The number of existing owners registered in {@code city}, compared case-insensitively
708	     * with collapsed whitespace.
709	     */
710	    private int countOwnersInCity(String city) {
711	        String normalized = normalizeHouseholdField(city);
712	        return (int) this.clinicService.findAllOwners().stream()
713	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
714	            .count();
715	    }
716	
717	    /**
718	     * The number of existing owners in {@code owner}'s city other than {@code owner} itself, compared
719	     * case-insensitively with collapsed whitespace. This is the count of owners already present in the
720	     * city that a newly created owner joins, mirroring the basis of the per-city create gate.
721	     */
722	    private long countOtherOwnersInCity(Owner owner) {
723	        String normalized = normalizeHouseholdField(owner.getCity());
724	        return this.clinicService.findAllOwners().stream()
725	            .filter(existing -> existing.getId() == null || !existing.getId().equals(owner.getId()))
726	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
727	            .count();
728	    }
729	
730	    /**
731	     * The effective registration date to store for a new owner: the date supplied on the request
732	     * when present, otherwise the current server date, in either case rolled forward to a business
733	     * day so it never falls on a weekend or public holiday (rolled forward to the next such day).
734	     * This single point of resolution is what every registration-date-derived value (the stored
735	     * date, the member id's fiscal-year segment, the per-day create-limit) is computed from.
736	     */
737	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
738	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
739	        return toBusinessDay(date);
740	    }
741	
742	    /**
743	     * The fixed list of public holidays that a registration date must not fall on. A date landing
744	     * on one of these is rolled forward, exactly as weekends are.
745	     */
746	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
747	        LocalDate.of(2026, 1, 1),
748	        LocalDate.of(2026, 1, 26),
749	        LocalDate.of(2026, 4, 25),
750	        LocalDate.of(2026, 12, 25),
751	        LocalDate.of(2026, 12, 28));
752	
753	    /**
754	     * Roll {@code date} forward to the next business day: a Saturday, Sunday, or listed public
755	     * holiday is advanced day by day until it lands on a non-holiday weekday, which is returned
756	     * unchanged.
757	     */
758	    private static LocalDate toBusinessDay(LocalDate date) {
759	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
760	                || PUBLIC_HOLIDAYS.contains(date)) {
761	            date = date.plusDays(1);
762	        }
763	        return date;
764	    }
765	
766	    /**
767	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
768	     * last name, compared case-insensitively.
769	     */
770	    private int countNamesakes(Owner owner) {
771	        String firstName = normalizeHouseholdField(owner.getFirstName());
772	        String lastName = normalizeHouseholdField(owner.getLastName());
773	        return (int) this.clinicService.findAllOwners().stream()
774	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
775	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
776	            .count();
777	    }
778	
779	    /**
780	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
781	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
782	     * unusually high daily signup volume.
783	     */
784	    private boolean isBulkSignupWarning() {
785	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
786	    }
787	
788	    /** The number of existing owners whose registration date is {@code date}. */
789	    private int countOwnersRegisteredOn(LocalDate date) {
790	        return (int) this.clinicService.findAllOwners().stream()
791	            .filter(existing -> date.equals(existing.getRegistrationDate()))
792	            .count();
793	    }
794	
795	    /**
796	     * The single derived key all duplicate detection flows through. Under the version-2 owner
797	     * identity it is the lower-case hex SHA-256 of {@code 'V2' + '|' + normalizedTelephone + '|' +
798	     * lowerEmail + '|' + soundex(lastName)}, mixing in the fixed {@link Owner#IDENTITY_VERSION_TAG
799	     * 'V2' version tag} so no key produced under version 1 is produced again. It is formed from the
800	     * owner's already-normalized fields (the email is already lower-cased, the telephone already in
801	     * E.164 form, and the last name reduced to its {@link #soundex(String) Soundex} code). Because
802	     * the telephone is part of the key, two owners with the same last name and postcode but
803	     * different telephones resolve to different keys and are both allowed (the later one becoming a
804	     * possible duplicate rather than a hard conflict).
805	     */
806	    private static String identityKey(Owner owner) {
807	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
808	        String email = owner.getEmail() == null ? "" : owner.getEmail();
809	        String keyMaterial = String.join("|",
810	            Owner.IDENTITY_VERSION_TAG, telephone, email, soundex(owner.getLastName()));
811	        return Owner.sha256HexLower(keyMaterial);
812	    }
813	
814	    /**
815	     * Whether {@code owner}'s {@link #identityKey} equals a non-deleted existing owner's, which is
816	     * the sole duplicate condition: the previously separate telephone, email and household checks -
817	     * including the household-duplicate check derived from the {@code householdId} - are now all
818	     * expressed through this one identity key, so only an exact key match is a duplicate and a create
819	     * that trips it is rejected with {@code 409 CONFLICT}. Soft-deleted owners are ignored.
820	     */
821	    private boolean isDuplicate(Owner owner) {
822	        String key = owner.getIdentityKey();
823	        return this.clinicService.findAllOwners().stream()
824	            .filter(existing -> !existing.isDeleted())
825	            .map(Owner::getIdentityKey)
826	            .filter(existing -> existing != null)
827	            .anyMatch(key::equals);
828	    }
829	
830	    /** Common street-type abbreviations expanded during address normalization. */
831	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
832	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
833	
834	    /**
835	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
836	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
837	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
838	     * string when {@code address} is null or blank after normalization.
839	     */
840	    private static String normalizeAddress(String address) {
841	        if (address == null) {
842	            return "";
843	        }
844	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
845	        if (collapsed.isEmpty()) {
846	            return "";
847	        }
848	        StringBuilder sb = new StringBuilder(collapsed.length());
849	        for (String token : collapsed.split(" ")) {
850	            if (sb.length() > 0) {
851	                sb.append(' ');
852	            }
853	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
854	        }
855	        return sb.toString();
856	    }
857	
858	    /**
859	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
860	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
861	     */
862	    private static String normalizeHouseholdField(String value) {
863	        if (value == null) {
864	            return "";
865	        }
866	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
867	    }
868	
869	    /**
870	     * The American Soundex code of {@code value}: the retained first letter followed by up to three
871	     * digits encoding the remaining consonants, right-padded with zeros to length four. Non-letters
872	     * are ignored, adjacent letters coding to the same digit (including when separated by 'H' or 'W')
873	     * are coded once, and vowels (with 'Y') act as separators. Returns the empty string when
874	     * {@code value} holds no letters. Phonetically similar last names share a code, which is what the
875	     * identity key and the possible-duplicate soft match compare on.
876	     */
877	    private static String soundex(String value) {
878	        if (value == null) {
879	            return "";
880	        }
881	        StringBuilder letters = new StringBuilder();
882	        for (char c : value.toCharArray()) {
883	            if (c < 128 && Character.isLetter(c)) {
884	                letters.append(Character.toUpperCase(c));
885	            }
886	        }
887	        if (letters.length() == 0) {
888	            return "";
889	        }
890	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
891	        char previous = soundexDigit(letters.charAt(0));
892	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
893	            char c = letters.charAt(i);
894	            if (c == 'H' || c == 'W') {
895	                continue;
896	            }
897	            char digit = soundexDigit(c);
898	            if (digit != '0' && digit != previous) {
899	                code.append(digit);
900	            }
901	            previous = digit;
902	        }
903	        while (code.length() < 4) {
904	            code.append('0');
905	        }
906	        return code.toString();
907	    }
908	
909	    /** The Soundex digit for an upper-case letter, or {@code '0'} for letters that are not coded. */
910	    private static char soundexDigit(char c) {
911	        switch (c) {
912	            case 'B': case 'F': case 'P': case 'V':
913	                return '1';
914	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
915	                return '2';
916	            case 'D': case 'T':
917	                return '3';
918	            case 'L':
919	                return '4';
920	            case 'M': case 'N':
921	                return '5';
922	            case 'R':
923	                return '6';
924	            default:
925	                return '0';
926	        }
927	    }
928	
929	    /**
930	     * Existing owners that share {@code owner}'s household, i.e. resolve to the same
931	     * {@link #householdId(Owner) householdId}. Household membership is defined by that single derived
932	     * key rather than re-derived from the underlying fields here, so the household is described in one
933	     * place and every household-keyed value stays consistent with it.
934	     */
935	    private List<Owner> findHousemates(Owner owner) {
936	        String householdId = householdId(owner);
937	        return this.clinicService.findAllOwners().stream()
938	            .filter(existing -> !existing.isDeleted())
939	            .filter(existing -> householdId(existing).equals(householdId))
940	            .toList();
941	    }
942	
943	    /**
944	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
945	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
946	     */
947	    private int countHouseholdMembers(Owner owner) {
948	        return findHousemates(owner).size() + 1;
949	    }
950	
951	    /**
952	     * The membership level ceiling for a newly registered {@code owner}, derived from the household it
953	     * joins: one above the current maximum {@link Owner#getMembershipLevel() membershipLevel} among the
954	     * existing housemates (owners sharing the same {@code householdId}), so a new owner's reported level
955	     * can never exceed one above the household's current best. Returns {@code null} - meaning no ceiling
956	     * applies - when the owner has no existing household member.
957	     */
958	    private Integer membershipLevelCapForHousehold(Owner owner) {
959	        OptionalInt maxLevel = findHousemates(owner).stream()
960	            .mapToInt(Owner::getMembershipLevel)
961	            .max();
962	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
963	    }
964	
965	    /**
966	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
967	     * same last name (compared case-insensitively with collapsed whitespace) and postcode. Under the
968	     * version-2 owner identity it is the first 12 hex characters of SHA-256 over
969	     * {@code 'V2' + '|' + normalizedLastName + '|' + postcode} (the empty string standing in for a
970	     * missing postcode), mixing in the fixed {@link Owner#IDENTITY_VERSION_TAG 'V2' version tag} so
971	     * no household id produced under version 1 is produced again. Housemates always resolve to the
972	     * same value regardless of registration order, and owners sharing a last name and postcode share
973	     * it automatically.
974	     */
975	    private static String householdId(Owner owner) {
976	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
977	        String keyMaterial = String.join("|",
978	            Owner.IDENTITY_VERSION_TAG, normalizeHouseholdField(owner.getLastName()), postcode);
979	        return Owner.sha256Hex(keyMaterial).substring(0, 12);
980	    }
981	}
